// Parse AI response and apply state machine logic
const aiOutput = $json.output || $json.text || '{}';
const prevContext = $('Prepare AI Context').item.json;

let parsed;
try {
  // Extract JSON from AI response (might be wrapped in markdown)
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  parsed = { intent: 'OTHER', extracted: {}, naturalResponse: aiOutput };
}

const intent = parsed.intent || 'OTHER';
const extracted = parsed.extracted || {};
let naturalResponse = parsed.naturalResponse || '';

// Current session values
let service = prevContext.sessionService || extracted.service || null;
let professional = prevContext.sessionProfessional || extracted.professional || null;
let preferredDate = prevContext.sessionDate || extracted.date || null;
let preferredTime = prevContext.sessionTime || extracted.time || null;
let currentState = prevContext.currentState;

// Update with newly extracted values
if (extracted.service) service = extracted.service;
if (extracted.professional) professional = extracted.professional;
if (extracted.date) preferredDate = extracted.date;
if (extracted.time) preferredTime = extracted.time;

// ========================================
// STATE MACHINE: Determine next action
// ========================================
let action = 'REPLY';
let response = null;
let needsApiCall = null;
let showList = null;

if (intent === 'BOOK' || currentState.startsWith('AWAITING_')) {
  // BOOKING FLOW - Check what's missing IN ORDER

  if (!service) {
    currentState = 'AWAITING_SERVICE';
    showList = {
      type: 'services',
      items: prevContext.services,
      header: '💇 Nuestros Servicios',
      body: naturalResponse || '¿Qué servicio te gustaría?'
    };
  } else if (!professional) {
    currentState = 'AWAITING_PROFESSIONAL';
    showList = {
      type: 'professionals',
      items: prevContext.professionals,
      header: '💈 Nuestros Profesionales',
      body: naturalResponse || `Elegiste *${service}*. ¿Con quién te gustaría atenderte?`
    };
  } else if (!preferredDate) {
    currentState = 'AWAITING_DATE';
    response = {
      type: 'text',
      text: { body: naturalResponse || `Perfecto! *${service}* con *${professional}*. 📅 ¿Para qué fecha querés el turno?` }
    };
  } else if (!preferredTime) {
    currentState = 'AWAITING_TIME';
    action = 'FETCH_TIMES';
    needsApiCall = 'checkAvailability';
  } else {
    // All data collected!
    currentState = 'READY_TO_BOOK';
    action = 'BOOK_APPOINTMENT';
    needsApiCall = 'bookAppointment';
  }

} else if (intent === 'CANCEL') {
  currentState = 'AWAITING_CANCEL_SELECTION';
  action = 'FETCH_APPOINTMENTS';
  needsApiCall = 'checkAppointments';

} else if (intent === 'INFO') {
  currentState = 'IDLE';
  const serviceList = prevContext.services.join(', ');
  const profList = prevContext.professionals.join(', ');
  response = {
    type: 'text',
    text: { body: `ℹ️ *${prevContext.shopName}*\n\n💇 *Servicios:* ${serviceList}\n💈 *Profesionales:* ${profList}\n\n¿Querés reservar un turno?` }
  };

} else if (intent === 'GREET') {
  currentState = 'IDLE';
  response = {
    type: 'text',
    text: { body: naturalResponse || `¡Hola! 👋 Bienvenido a *${prevContext.shopName}*. ¿Querés reservar un turno?` }
  };

} else {
  // UNKNOWN - provide help
  response = {
    type: 'text',
    text: { body: naturalResponse || `Puedo ayudarte a:\n\n• *Reservar* un turno\n• *Cancelar* un turno\n• Ver *info* de servicios\n\n¿Qué querés hacer?` }
  };
}

// Build list response if needed
if (showList) {
  const rows = showList.items.slice(0, 10).map(item => ({
    id: item,
    title: item.slice(0, 24),
    description: ''
  }));
  response = {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: showList.header },
      body: { text: showList.body },
      footer: { text: prevContext.shopName },
      action: {
        button: 'Ver Opciones',
        sections: [{ title: 'Opciones', rows: rows }]
      }
    }
  };
}

return {
  action: action,
  response: response,
  needsApiCall: needsApiCall,
  updateSession: {
    current_state: currentState,
    intent: intent === 'GREET' ? null : (intent === 'BOOK' ? 'BOOK' : prevContext.currentIntent),
    service: service,
    professional: professional,
    preferred_date: preferredDate,
    preferred_time: preferredTime
  },
  context: {
    sender: prevContext.sender,
    userName: prevContext.userName,
    shopName: prevContext.shopName,
    service: service,
    professional: professional,
    preferredDate: preferredDate,
    preferredTime: preferredTime
  }
};

const slots = $json;
const context = $('State Machine').item.json.context;
const shopName = context.shopName;
const preferredDate = context.preferredDate;

if (!slots || slots.length === 0) {
  return {
    response: {
      type: 'text',
      text: { body: `😕 No hay horarios disponibles para el ${preferredDate} con ${context.professional}.\n\n¿Querés probar otra fecha?` }
    },
    updateSession: $('State Machine').item.json.updateSession
  };
}

const rows = slots.slice(0, 10).map(slot => {
  const time = slot.start_time ? slot.start_time.substring(11, 16) : slot;
  return { id: time, title: time, description: '' };
});

const dateParts = preferredDate.split('-');
const formattedDate = `${dateParts[2]}/${dateParts[1]}`;

return {
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '🕐 Horarios Disponibles' },
      body: { text: `📅 *${formattedDate}* con *${context.professional}*\n\n¿A qué hora te viene bien?` },
      footer: { text: shopName },
      action: {
        button: 'Ver Horarios',
        sections: [{ title: 'Horarios', rows: rows }]
      }
    }
  },
  updateSession: $('State Machine').item.json.updateSession
};

const result = $json;
const context = $('State Machine').item.json.context;

if (result.success) {
  const dateParts = context.preferredDate.split('-');
  const formattedDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
  const formattedTime = context.preferredTime.substring(0, 5);

  return {
    response: {
      type: 'text',
      text: { body: `✅ *¡Reserva Confirmada!*\n\n💇 *Servicio:* ${context.service}\n💈 *Profesional:* ${context.professional}\n📅 *Fecha:* ${formattedDate} a las ${formattedTime}\n\n📍 *Lugar:* ${context.shopName}\n\n¡Te esperamos! 🎉` }
    },
    updateSession: { current_state: 'IDLE', intent: null, service: null, professional: null, preferred_date: null, preferred_time: null }
  };
} else {
  return {
    response: {
      type: 'text',
      text: { body: `❌ Hubo un problema con la reserva.\n\nError: ${result.error || 'Desconocido'}\n\n¿Querés intentar con otro horario?` }
    },
    updateSession: { current_state: 'AWAITING_TIME', intent: 'BOOK', service: context.service, professional: context.professional, preferred_date: context.preferredDate }
  };
}

const appointments = $json;
const context = $('State Machine').item.json.context;

if (!appointments || appointments.length === 0) {
  return {
    response: {
      type: 'text',
      text: { body: `No tenés turnos pendientes. 😊\n\n¿Querés reservar uno nuevo?` }
    },
    updateSession: { current_state: 'IDLE', intent: null }
  };
}

const rows = appointments.slice(0, 10).map(apt => {
  const date = apt.start_time ? apt.start_time.substring(0, 10) : '';
  const time = apt.start_time ? apt.start_time.substring(11, 16) : '';
  const dateParts = date.split('-');
  const shortDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}` : date;

  return {
    id: apt.id,
    title: `${shortDate} ${time}`.slice(0, 24),
    description: `${apt.service_name || 'Servicio'} - ${apt.professional_name || ''}`
  };
});

return {
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '📋 Tus Turnos' },
      body: { text: 'Seleccioná el turno que querés cancelar:' },
      footer: { text: context.shopName },
      action: {
        button: 'Ver Turnos',
        sections: [{ title: 'Turnos Pendientes', rows: rows }]
      }
    }
  },
  updateSession: { current_state: 'AWAITING_CANCEL_SELECTION', intent: 'CANCEL' }
};
